<template><section class="max-w-lg"><h2 class="text-2xl font-bold mb-6">{{editing?'Chỉnh sửa Crop':'Thêm Crop'}}</h2><form @submit.prevent="save"><label>Tên Crop<input v-model="cropName" required class="mt-1 block w-full rounded bg-white/10 border border-white/20 p-2"/></label><p v-if="error" class="mt-3 text-error">{{error}}</p><button class="mt-4 px-4 py-2 rounded bg-primary text-secondary" :disabled="saving">{{saving?'Đang lưu…':'Lưu'}}</button></form></section></template><script setup>import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{adminApi}from'../../api/adminService';const route=useRoute(),router=useRouter(),editing=computed(()=>!!route.params.id),cropName=ref(''),error=ref(''),saving=ref(false);onMounted(async()=>{if(editing.value)try{cropName.value=(await adminApi.crop(route.params.id)).data.cropName}catch(e){error.value='Không thể tải Crop.'}});const save=async()=>{saving.value=true;try{editing.value?await adminApi.updateCrop(route.params.id,{cropName:cropName.value}):await adminApi.createCrop({cropName:cropName.value});router.push({name:'admin-crops'})}catch(e){error.value=e.response?.data?.message||'Không thể lưu Crop.'}finally{saving.value=false}}</script>
